archetype (adl_version=1.4; uid=3e00db0d-6078-49cc-8016-ecee504fa71a)
	openEHR-EHR-EVALUATION.smokeless_tobacco_summary.v1

concept
	[at0000]	-- Smokeless tobacco summary
language
	original_language = <[ISO_639-1::en]>
	translations = <
		["sv"] = <
			language = <[ISO_639-1::sv]>
			author = <
				["name"] = <"Carrick Gillespie / Erik Sundvall">
				["organisation"] = <"Omniq AB / Region Östergötland + Linköping University">
				["email"] = <"carrickg@gmail.com / erik.sundvall@regionostergotland.se">
			>
		>
		["nb"] = <
			language = <[ISO_639-1::nb]>
			author = <
				["name"] = <"Kristian Berg, Vebjørn Arntzen">
				["organisation"] = <"Universitetssykehuset Nord Norge - Regional forvaltning EPJ, Oslo University Hospital">
				["email"] = <"kristian.berg@unn.no, varntzen@ous-hf.no">
			>
			accreditation = <"*">
		>
	>
description
	original_author = <
		["name"] = <"Heather Leslie">
		["organisation"] = <"Atomica Informatics, Australia">
		["email"] = <"heather.leslie@atomicainformatics.com">
		["date"] = <"2009-06-21">
	>
	details = <
		["sv"] = <
			language = <[ISO_639-1::sv]>
			purpose = <"Sammanfattande eller beständig information om en individs snusande eller annat rökfritt tobaksbruk.">
			use = <"Används för att beskriva sammanfattad information om individens användning av rökfria tobaks-innehållande produkter, exempelvis snus.

Denna arketyp kan användas för att beskriva både nuvarande och tidigare användning av rökfri tobak.

Arketypen omfattar användningen av alla typer av rökfri tobak på grund av de tillhörande hälsoriskerna. Detaljer om nikotinmängd och tillsatser har lämnats utanför arketypen, men kan läggas till (med hjälp av ytterligare arketyper) under \"episoddetaljer\" om det behövs.

\"Per typ\"-avsnittet kan repeteras en gång per typ och ger möjlighet att registrera specifika detaljer och episoder om varje typ. Ofta använder individer bara en sorts rökfri tobak, exempelvis snus. Om flera typer av rökfri tobak används så registreras de uppgifterna i andra instanser av \"Per typ\"-avsnittet.

Att bruket av en typ av rökfri tobak varierar i omfattning över tid kan fångas med det repeterbara \"Per episod\"-avsnittet. Detta avsnitt gör det möjligt att registrera ett mycket detaljerat mönster för användningen av tobak för varje typ av tobak som används, såsom daglig användning av snus, lika väl som tillfällig användning av tuggtobak på semestern.

Anledningar för att avsluta en episod och starta en ny kommer vanligen återspegla lokala datainsamlingspreferenser, inklusive om individen:
- slutar användningen under en betydande tidsperiod (vilket sannolikt kommer att vara lokalt definierat) eller
- signifikant ändrar användningsmönster eller mängd

För att registrera beskrivande information (t.ex. fritext) om rökfritt tobaksbruk från befintliga eller gamla vård-IT-system i arketyp-baserade system, används lämpligen dataelementet \"Övergripande beskrivning\".">
