ontology
	term_definitions = <
		["en"] = <
			items = <
				["at0000"] = <
					text = <"Smokeless tobacco summary">
					description = <"Summary or persistent information about smokeless tobacco use by an individual.">
				>
				["at0001"] = <
					text = <"Tree">
					description = <"@ internal @">
				>
				["at0003"] = <
					text = <"Current user">
					description = <"The individual is a current user of any type of smokeless tobacco.">
				>
				["at0005"] = <
					text = <"Former user">
					description = <"The individual has previously used smokeless tobacco, but is not a current user.">
				>
				["at0006"] = <
					text = <"Never used">
					description = <"Individual has never used any type of smokeless tobacco.">
				>
				["at0013"] = <
					text = <"Episode start date">
					description = <"Date when this episode commenced.">
					comment = <"Can be a partial date, for example, only a year.">
				>
				["at0014"] = <
					text = <"Quit date">
					description = <"Date when the individual last used the specified type of tobacco.">
					comment = <"Can be a partial date, for example, only a year. Definitions for a 'Quit date' vary enormously and can be defined using the 'Quit data definition' data element in the Protocol section of this archetype. This date will be identical to the 'Episode end date' for the most recent episode. This date could be used by decision support guidance to determine if the individual is at risk of relapse, for example in the first 12 months since quitting.">
				>
				["at0015"] = <
					text = <"Regular use commenced">
					description = <"The date or partial date when the individual first started frequent or regular, but non-daily, use of smokeless tobacco of any type.">
					comment = <"Can be a partial date, for example, only a year. For example, this date could represent when the individual commenced using smokeless tobacco every Friday night or at parties.">
				>
				["at0016"] = <
					text = <"Overall quit date">
					description = <"The date when the individual last ceased using smokeless tobacco of any type.">
					comment = <"Can be a partial date, for example, only a year. This date could be used by decision support guidance to determine if the individual is at risk of relapse, for example in the first 12 months since quitting.">
				>
				["at0017"] = <
					text = <"Pack years">
					description = <"Estimate of the cumulative amount of smokeless tobacco used over a lifetime, for the specified type of smokeless tobacco.">
					comment = <"Commonly used in assessment of snus use. It is calculated by multiplying the number of packs of snus used per day by the number of years the individual has used. One pack-year is the
equivalent of using one packet of snus daily for 1 year. The definition of a pack can be recorded in the protocol of this archetype using the 'Pack definition' data element.">
				>
				["at0019"] = <
					text = <"Overall comment">
					description = <"Additional narrative about all smokeless tobacco use, not captured in other fields.">
					comment = <"For example: stopped snusing or reduced amount on becoming pregnant.">
				>
				["at0021"] = <
					text = <"Tree">
					description = <"@ internal @">
				>
				["at0022"] = <
					text = <"Last updated">
					description = <"The date this smokeless tobacco summary was last updated.">
				>
				["at0023"] = <
					text = <"Typical frequency">
					description = <"Estimate of number of times that an individual uses smokeless tobacco per time period.">
					comment = <"For example: the number of 'bags', 'pinches' or 'portions' per day or per week.">
				>
				["at0025"] = <
					text = <"Number of quit attempts">
					description = <"Total number of times the individual has attempted to stop using the specified type of smokeless tobacco within this episode.">
				>
				["at0026"] = <
					text = <"Episode details">
					description = <"Additional structured details about the specified episode of smokeless tobacco use.">
				>
				["at0029"] = <
					text = <"Per type">
					description = <"Details about use of a specified type of smokeless tobacco.">
				>
				["at0030"] = <
					text = <"Pattern">
					description = <"Details about a discrete period of use of the specified type of smokeless tobacco.">
					comment = <"The typical pattern of use can be made more granular by coding the free text option with a terminology or a local value set in a template.">
				>
				["at0043"] = <
					text = <"Overall description">
					description = <"Narrative summary about the individual's overall smokeless tobacco use pattern and history.">
					comment = <"Use this data element to record a narrative description of the smokeless tobacco use for this individual or to incorporate unstructured information about smokeless tobacco use from existing or legacy clinical systems into an archetyped format.">
				>
				["at0052"] = <
					text = <"Status">
					description = <"Statement about current use of the specified type of smokeless tobacco.">
				>
				["at0053"] = <
					text = <"Description">
