				["at0073"] = <
					text = <"Extension">
					description = <"Additional information required to capture local content or to align with other reference models/formalisms.">
					comment = <"For example: local information requirements or additional metadata to align with FHIR or CIMI equivalents.">
				>
				["at0074"] = <
					text = <"Overall pack years">
					description = <"Estimate of the cumulative amount of smokeless tobacco used over a lifetime, for all types of smokeless tobacco.">
					comment = <"Commonly used in assessment of snus use. It is calculated by multiplying the number of packs of snus, or other types of smokeless tobacco, used per day by the number of years the individual has used. One pack-year is the
equivalent of using one packet of smokeless tobacco daily for 1 year. The definition of a pack can be recorded in the protocol of this archetype using the 'Pack definition' data element.">
				>
				["at0075"] = <
					text = <"Current user definition">
					description = <"The applied definition for the 'Current user' value in each of the 'Status' data elements used in this archetype.">
					comment = <"Definition may need to be specified per type.">
				>
				["at0076"] = <
					text = <"Former user definition">
					description = <"The applied definition for the 'Former user' value in each of the 'Status' data elements used in this archetype.">
					comment = <"Definition may need to be specified per type.">
