				["at0081"] = <
					text = <"Episode label">
					description = <"Identification of an episode of smokeless tobacco use.">
					comment = <"The label may be represented either as a number in a sequence and/or a named event. For example: '2' as the second episode within a sequence of episodes; or 'Pregnancy with twins' if describing the use of smokeless tobacco during a health event such as during a specific pregnancy.">
				>
				["at0082"] = <
					text = <"Episode end date">
					description = <"Date when this episode ceased.">
					comment = <"Can be a partial date, for example, only a year. This data field will be empty if the episode is current and ongoing.">
				>
				["at0083"] = <
					text = <"Daily">
					description = <"Use of the specified type of smokeless tobacco at least once every day.">
				>
				["at0084"] = <
					text = <"Non-daily">
