					comment = <"Kan være en deldato, for eksempel årstall.">
				>
				["at0014"] = <
					text = <"Sluttdato">
					description = <"Datoen da individet sist brukte den spesifiserte typen røykfri tobakk.">
					comment = <"Kan være en deldato, for eksempel årstall. Definisjoner for \"Sluttdato\" varierer enormt og kan defineres ved å bruke datalementet \"Definisjon på Sluttdato\" i protokolldelen av denne arketypen. Denne datoen vil være identisk med \"Episodens sluttdato\" for den siste episoden. Denne datoen kan brukes av beslutningsstøttesystemer for å beregne om individet er i faresonen for tilbakefall, for eksempel i løpet av de først 12 månedene etter å ha sluttet.">
				>
				["at0015"] = <
					text = <"Start regelmessig bruk">
					description = <"Dato eller deldato da individet for første gang begynte å bruke røykfri tobakk hyppig eller regelmessig, men ikke daglig.">
					comment = <"Kan være en deldato, for eksempel kun årstall. For eksempel kan denne datoen representere tidspunktet da individet begynte å bruke røykfri tobakk hver fredagskveld eller på fest.">
				>
				["at0016"] = <
					text = <"Overordnet sluttdato">
					description = <"Datoen da individet sist brukte en hvilken som helst type røykfri tobakk.">
					comment = <"Kan være en deldato, for eksempel årstall. Denne datoen kan brukes av beslutningsstøttesystemer for å beregne om individet er i faresonen for tilbakefall, for eksempel i løpet av de først 12 månedene etter å ha sluttet.">
				>
				["at0017"] = <
					text = <"Pakkeår">
					description = <"Anslått kumulativ mengde tobakk brukt av den spesifiserte typen tobakk.">
					comment = <"Vanligvis gjøres vurderingen på snusbruk. Den kalkuleres ved å multiplisere antall pakker snus brukt hver dag med antall år individet har brukt snus. Et pakkeår tilsvarer 365 pakker snus. Definisjonen på en pakke kan registreres i protokollen av denne arketypen, ved å bruke dataelementet \"Pakkedefinisjon\".">
				>
				["at0019"] = <
					text = <"Overordnet kommentar">
					description = <"Ytterligere fritekst om all bruk av røykfri tobakk som ikke er omfattet av andre felt.">
					comment = <"For eksempel: Sluttet å bruke snus eller reduserte mengde ved graviditet.">
				>
				["at0021"] = <
					text = <"Tree">
					description = <"@ internal @">
				>
				["at0022"] = <
					text = <"Sist oppdatert">
					description = <"Datoen da sammendraget av bruk av røykfri tobakk sist ble oppdatert.">
				>
				["at0023"] = <
					text = <"Typisk hyppighet">
					description = <"Anslått antall ganger individer bruker røykfri tobakk i en spesifisert tidsperiode.">
					comment = <"For eksempel: Antall \"poser\", \"priser\" eller \"porsjoner\" per dag eller per uke.">
				>
				["at0025"] = <
					text = <"Antall forsøk på å slutte">
					description = <"Totalt antall ganger individet har forsøkt å slutte å bruke den spesifiserte typen røykfri tobakk innenfor denne episoden.">
				>
				["at0026"] = <
					text = <"Episodedetaljer">
					description = <"Ytterligere strukturerte detaljer om den spesifiserte episoden med bruk av røykfri tobakk.">
				>
				["at0029"] = <
					text = <"Per type">
					description = <"Detaljer om bruk for en spesifikk type røykfri tobakk.">
					comment = <"Navnebegrensningen på dette clusteret gjør det mulig å enkelt spesifisere hver type røykfri tobakk i templater, eller i en applikasjon. Listen over navn kan utvides i en applikasjon dersom flere typer røykfri tobakk finnes lokalt.">
				>
				["at0030"] = <
					text = <"Mønster">
					description = <"Detaljer om en avgrenset bruksperiode for den spesifiserte typen røykfri tobakk.">
					comment = <"Typisk bruksmønster gjøres mer finkornet ved å kode med en terminologi eller med et lokalt verdisett i et templat.">
				>
				["at0043"] = <
					text = <"Overordnet beskrivelse">
