				["at0079"] = <
					text = <"Definisjon av Aldri brukt">
					description = <"Den anvendte definisjonen på verdien \"Aldri brukt\" i dataelementet \"Status\" benyttet i denne arketypen.">
					comment = <"Definisjonen kan måtte spesifiseres per tobakkstype. For eksempel trenger ikke definisjonen være null, men mindre enn en spesifikk mengde brukt i løpet av et spesifikt tidsintervall.">
				>
				["at0080"] = <
