		["sv"] = <
			items = <
				["at0000"] = <
					text = <"Sammanfattning av snusvanor och annat bruk av rökfri tobak">
					description = <"Samlad information om en individs bruk av rökfri tobak, exempelvis snus">
				>
				["at0001"] = <
					text = <"Tree">
					description = <"@ internal @">
				>
				["at0003"] = <
					text = <"Aktiv brukare">
					description = <"Individen använder någon form av rökfri tobak">
				>
				["at0005"] = <
					text = <"Före detta brukare">
					description = <"Individen har tidigare använt någon form av rökfri tobak men har slutat.">
				>
				["at0006"] = <
					text = <"Har aldrig använt">
					description = <"Individen har aldrig använt någon form av rökfri tobak.">
				>
				["at0013"] = <
					text = <"Episodens startdatum">
					description = <"Datum när den här episoden startade.">
					comment = <"Kan vara del av ett datum, till exempel bara ett årtal.">
				>
				["at0014"] = <
					text = <"Slutdatum">
					description = <"Datum då personen senast använde den angivna tobakstypen.">
					comment = <"Kan vara ett partiellt datum, till exempel bara ett årtal. Definition av ett \"Slutdatum\" varierar kraftigt och kan därför definieras i dataelementet \"Definition av slutdatum\" i \"protocol\"-delen i den här arketypen. 

För den senaste episoden kommer detta datum att vara identiskt med \"Episodens slutdatum\" utifall individen under episoden har slutat bruka rökfri tobak. Detta datum kan användas av beslutsstödssystem för att avgöra om personen är i riskzonen för återfall, till exempel under de första 12 månaderna sedan hen slutade.">
				>
				["at0015"] = <
					text = <"Började använda rökfri tobak regelbundet">
					description = <"Datum eller del av datum när individen först började använda någon sorts rökfri tobak regelbundet, men inte dagligen.">
					comment = <"Det kan vara del av ett datum, till exempel bara ett årtal. Datumet kan till exempel representera när individen började använda rökfri tobak varje fredagskväll eller på fester.">
				>
				["at0016"] = <
					text = <"Övergripande slutdatum">
					description = <"Det datum då individen (senast) helt slutade använda snus och annan rökfri tobak.">
					comment = <"Kan vara del av ett datum, till exempel bara ett årtal. Detta datum kan användas av beslutsstödssystem för att avgöra om individen är i riskzonen för återfall, till exempel under de första 12 månaderna sedan hen slutade.">
				>
				["at0017"] = <
					text = <"Paketår">
					description = <"En uppskattning av den totala mängden av denna sorts tobaksprodukt som en person har använt under sin livstid.">
					comment = <"Används för att bedöma exempelvis snusförbrukning. Det beräknas genom att multiplicera antalet snusade dosor per dag med det antal år som personen snusat. Ett paketår motsvarar en snusdosa dagligen under ett år. Definitionen av dosa/förpackning/paket kan anges fältet \"Definition av paket\" i protokoll-delen (\"Protocol\") av den här arketypen.">
				>
				["at0019"] = <
					text = <"Övergripande kommentar">
					description = <"Ytterligare övergripande beskrivning av allt rökfritt tobaksbruk som inte redan beskrivits i andra fält.">
					comment = <"Exempelvis: slutade snusa eller minskade snusning i samband med graviditet">
				>
				["at0021"] = <
					text = <"Tree">
					description = <"@ internal @">
				>
				["at0022"] = <
					text = <"Senast uppdaterad">
					description = <"Datum när denna sammanfattning av individens rökfria tobaksvanor uppdaterades senast.">
				>
				["at0023"] = <
					text = <"*Typical frequency (en)">
					description = <"*Estimate of number of times that an individual uses smokeless tobacco per time period. (en)">
					comment = <"Exempelvis hur många \"portioner\" (\"pris\" eller \"prilla\" för lössnus) som används per dag eller vecka.">
				>
				["at0025"] = <
					text = <"Antal försök att sluta">
					description = <"Totalt antal gånger som personen har försökt sluta använda den angivna typen rökfri tobak under denna episod.">
				>
				["at0026"] = <
					text = <"Episoddetaljer">
					description = <"Ytterligare strukturerade detaljer om episoden.">
				>
				["at0029"] = <
					text = <"Per typ">
					description = <"Detaljer om en specifik typ av rökfri tobaksanvändning, exempelvis snusning.">
					comment = <"Detta \"run-time name constraint\" för detta \"Cluster\" (delträd) gör det enkelt att skapa typ-specifika delar i \"templates\" (openEHR-mallar), eller att låta ett IT-system dynamiskt generera specifika delar vid användning. Det är tillåtet att lägga till ytterligare typer av rökfri tobak, om det har identifierats som ett lokalt behov.">
				>
				["at0030"] = <
					text = <"Användningsmönster">
					description = <"Detaljer om konsumtionsmönstret under episoden, för den angivna typen av tobak .
">
					comment = <"Det typiska konsumtionsmönstret kan anges mer granulärt genom att koda textfältet med en terminologi eller en lokal vallista i en template.">
				>
				["at0043"] = <
					text = <"Övergripande beskrivning">
					description = <"Beskrivande sammanfattning av en individs vanor och historik avseende snusning och annat rökfritt tobaksbruk.">
					comment = <"*Use this data element to record a narrative description of the smokeless tobacco use for this individual or to incorporate unstructured information about smokeless tobacco use from existing or legacy clinical systems into an archetyped format. (en)">
				>
				["at0052"] = <
					text = <"Status">
					description = <"Uttalande om nuvarande bruk av den angivna typen av rökfri tobak.">
				>
				["at0053"] = <
					text = <"Beskrivning">
					description = <"Beskrivande sammanfattning om bruk av den angivna typen av rökfri tobak">
				>
				["at0059"] = <
					text = <"Före detta brukare">
					description = <"Individen har tidigare använt denna form av rökfri tobak men har slutat.">
				>
				["at0061"] = <
					text = <"Aktiv brukare">
					description = <"Individen använder denna form av rökfri tobak">
				>
				["at0064"] = <
					text = <"Per episod">
					description = <"Detaljerad beskrivning av en specifik användningsepisod för den angivna typen av tobak.">
				>
				["at0065"] = <
					text = <"Typisk användning (massa)">
					description = <"Uppskattad motsvarande mängd lös tobak som används.">
					comment = <"Detta dataelement används typiskt för lös tobak och är överflödig om ett värde är registrerat för \"Typisk användning (enheter)\".">
				>
				["at0069"] = <
					text = <"Kommentar">
					description = <"Ytterligare beskrivning av användningen av denna sorts tobaksprodukt, som inte redan beskrivits i andra fält.">
				>
				["at0071"] = <
					text = <"Definition av slutdatum">
					description = <"Definitionen av \"slutdatum\" som använts i denna arketyps fält/dataelement.">
				>
				["at0072"] = <
					text = <"Definition av ett Paket">
					description = <"Definitionen av storleken på paket/förpackning/snusdosa som används som en del av algoritmen för att beräkna \"Paketår\" dataelement som används i denna arketyp.">
					comment = <"Definition kan behöva anges per typ. Till exempel kan antalet gram i en låda som används för snus vara olika i olika typer av lådor; Massan av lös tobak i en låda som används för lösa typer av tobaksrök.">
				>
				["at0073"] = <
					text = <"Utökning">
					description = <"Plats för att infoga ytterligare information som krävs för att fånga upp lokalt innehåll eller för att anpassa sig till andra referensmodeller/format.">
					comment = <"Exempelvis lokala informationskrav eller metadata för anpassning till FHIR- eller CIMI-motsvarigheter.">
				>
				["at0074"] = <
					text = <"Totala paketår">
					description = <"En uppskattning av den totala mängden rökfri tobak, av alla typer, som en person har använt under sin livstid.">
					comment = <"Används för att bedöma exempelvis snusförbrukning. Det beräknas genom att multiplicera antalet snusade dosor per dag med det antal år som personen snusat. Ett paketår motsvarar en snusdosa dagligen under ett år. Definitionen av dosa/förpackning/paket kan anges fältet \"Definition av paket\" i protokoll-delen (\"Protocol\") av den här arketypen.">
				>
				["at0075"] = <
					text = <"Definition av \"Aktiv brukare\"">
					description = <"Den tillämpade definitionen för \"Aktiv brukare\"-värdet i varje \"Status\" som används i den här arketypen.">
					comment = <"Definition kan behöva anges per typ.">
				>
				["at0076"] = <
					text = <"Definition av \"Före detta brukare\"">
					description = <"Den tillämpade definitionen för \"Före detta brukare\"-värdet i varje \"Status\" som används i den här arketypen.">
					comment = <"Definition kan behöva anges per typ.">
				>
				["at0077"] = <
					text = <"Typdetaljer">
					description = <"Plats för att infoga ytterligare strukturerad information om den angivna sortens rökfri tobaksanvändning">
				>
				["at0079"] = <
					text = <"Definition av \"Har aldrig använt\"">
					description = <"Den tillämpade definitionen för \"Har aldrig använt\"-värdet i varje \"Status\" som används i den här arketypen.">
					comment = <"Definitionen kan behöva anges per typ. Exempelvis så behöver den inte vara noll, men kanske istället mindre än en specificerad mängd använd under en specificerad tidsperiod.">
				>
				["at0080"] = <
					text = <"Började använda rökfri tobak dagligen">
					description = <"Datum eller del av datum när individen först började använda någon sorts rökfri tobak dagligen.">
					comment = <"Det kan vara del av ett datum, till exempel bara ett årtal.">
				>
				["at0081"] = <
					text = <"Episodbeteckning">
					description = <"Identifiering av (eller beskrivande beteckning för) en specifik konsumtionsepisod.">
					comment = <"Beteckningen kan antingen representeras som ett tal i en sekvens och/eller en namngiven händelse. Exempelvis: \"2\" som den andra episoden inom en sekvens av episoder; eller \"Graviditet med tvillingar\" om man beskriver tobaksbruket under en hälsorelaterad episod, t.ex. under en viss graviditet.">
				>
				["at0082"] = <
					text = <"Episodens slutdatum">
					description = <"Datum när den här episoden slutade.">
					comment = <"Kan vara del av ett datum, till exempel bara ett årtal. Det här fältet kommer att vara tomt om episoden är aktuell och pågående.">
				>
				["at0083"] = <
					text = <"Dagligen">
					description = <"Använder den angivna typen rökfri tobak minst en gång om dagen.">
				>
				["at0084"] = <
					text = <"Inte dagligen">
					description = <"Använder inte den angivna typen av rökfri tobak dagligen.">
				>
				["at0085"] = <
					text = <"Definition av \"Försök att sluta\"">
					description = <"Definitionen av avslutningsförsök som använts i denna arketyps fält \"Antal försök att sluta\".">
					comment = <"Exempelvis: \"slutade snusa en dag eller längre med avsikt att sluta\".">
				>
				["at0086"] = <
					text = <"Övergripande detaljer">
					description = <"Ytterligare strukturerade detaljer om den totala rökfria tobaksanvändningen.">
				>
				["at0087"] = <
					text = <"Kommentar till episod">
					description = <"Eventuell ytterligare beskrivning om användningen av den angivna typen rökfri tobak under den angivna episoden, som inte kunnat registrerats i andra fält.">
				>
				["at0089"] = <
					text = <"Övergripande status">
					description = <"Beskrivning av aktuellt bruk för alla typer av rökfri tobak">
				>
				["at0091"] = <
					text = <"Har aldrig använt">
					description = <"Individen har aldrig brukat någon form av rökfri tobak.">
				>
				["at0098"] = <
					text = <"Typ">
					description = <"Namnet på den specifika typen eller gruppen av rökfri tobak.">
					comment = <"Typ skulle exempelvis kunna vara snus eller gutka, medan en grupp kan vara \"tuggobak\".">
				>
				["at0099"] = <
					text = <"*Overall years of use (en)">
					description = <"*The cumulative number of years that the individual has used smokeless tobacco. (en)">
					comment = <"*This data element does not take into account the amount of tobacco used. (en)">
				>
				["at0100"] = <
					text = <"*Status (en)">
					description = <"">
				>
				["at0101"] = <
					text = <"*User (en)">
					description = <"*The individual used the specified type of smokeless tobacco during this episode. (en)">
				>
				["at0102"] = <
					text = <"*Non-user (en)">
					description = <"*The individual did not use the specified type of smokeless tobacco during this episode. (en)">
				>
			>
		>
	>

