					text = <"Episodens startdatum">
					description = <"*Date when this episode commenced. (en)">
					comment = <"*Can be a partial date, for example, only a year. (en)">
				>
				["at0015"] = <
					text = <"Episodens slut datum">
					description = <"Datum då episoden avslutades.">
					comment = <"Kan vara ett partiellt datum, till exempel endast ett år. Datafältet är tomt om episoden är aktuell och pågående.">
				>
				["at0016"] = <
					text = <"Specifikt substansnamn">
					description = <"Namn på den specifika substans som användes under episoden.">
					comment = <"Den registrerade uppgiften i fältet \"Substansnamn\" kanbli duplicerad om den specifika substansen redan har identifierats. Om uppgiften i dataelementet \"Substansnamn\" däremot avser en substansgrupp eller en substansklass kan detta dataelement användas för att identifiera en specifik substans och motivera att en separat episod registreras.">
				>
				["at0017"] = <
					text = <"Status">
					description = <"Rapporterad användning av den specifika substansen under den aktuella episoden.">
				>
				["at0018"] = <
					text = <"Episodens beskrivning">
					description = <" Beskrivning av användningen av den specifika substansen under episoden.">
				>
				["at0019"] = <
					text = <"Mönster">
					description = <"Typiskt användningsmönster för den specifika substansen under episoden.">
					comment = <"Detta dataelement är upprepbar för att möjliggöra registrering av flera olika användningsmönster. Det typiska användningsmönstret kan anges mer detaljerat genom kodning med en terminologi eller en lokal val lista, eller genom att använda datatypen Kvantitet (Quantity) i en template.">
				>
				["at0020"] = <
					text = <"*Daily (en)">
					description = <"*Using the substance at least once every day. (en)">
				>
				["at0021"] = <
					text = <"*Not daily (en)">
					description = <"*Not using the substance every day. (en)">
				>
				["at0023"] = <
					text = <"Typisk använd mängd">
					description = <"Typisk mängd av den specifika substansen som användes under episoden.">
					comment = <"Till exempel som en kvantitet, såsom \"6 g/vecka\", eller som fritext, exempelvis \"oregelbunden användning beroende på stressnivå, varierande mellan 1 och 10 gram per vecka\".">
				>
				["at0024"] = <
					text = <"Antal försök att sluta">
					description = <"Totalt antal gånger individen har försökt sluta använda den specifika substansen under denna episod.">
				>
				["at0025"] = <
					text = <"Episodens detaljer">
					description = <"Mer information om episoden.">
				>
				["at0026"] = <
					text = <"Episodens kommentar">
					description = <"Ytterligare beskrivning av användningen av den specifika substansen under denna episod som inte fångas i övriga fält.">
				>
				["at0027"] = <
					text = <"Övergripande detaljer">
					description = <"Ytterligare strukturerade detaljer om den övergripande substansanvändningen.">
				>
				["at0028"] = <
					text = <"Övergripande slutdatum">
					description = <"Datum då individen senast använde substansen.">
					comment = <"Kan vara ett partiellt datum, till exempel endast ett år.">
				>
				["at0029"] = <
					text = <"Item tree">
					description = <"@ internal @">
