    "termDefinitions" : {
      "en" : {
        "at0000.1" : {
          "@type" : "ARCHETYPE_TERM",
          "code" : "at0000.1",
          "text" : "Care unit",
          "description" : "An entity comprising one or more people and having a particular purpose.\nIn this context, the care unit is an organizational unit that provides health care.\n"
        },
        "at0003.1" : {
          "@type" : "ARCHETYPE_TERM",
          "code" : "at0003",
          "text" : "Identifier",
          "description" : "Identifier associated with the organisation.\nIn this context, the identifier of the care unit.",
          "comment" : "Occurrences for this data element is set to 1..* to allow for more than one Identifier to be recorded. Note that the ID data type contains multiple subcomponents for recording the ID value, type, issuer and assigner."
        },
        "at0004.1" : {
          "@type" : "ARCHETYPE_TERM",
          "code" : "at0004",
          "text" : "Role",
          "description" : "The relationship or role of the organisation to the individual or subject of care.\nIn this context, the role states that the organisation is of the type care unit."
        },
        "at0001.1" : {
          "@type" : "ARCHETYPE_TERM",
          "code" : "at0001",
          "text" : "Name",
          "description" : "The unstructured name or label for the organisation. In this context, the name of the care unit.",
          "comment" : "For example: 'Royal Children's Hospital'; 'ABC District Nursing Service'; 'YNWA Oslo' or 'JB Smith Lawyers'."
        }
      },
      "nb" : { },
      "de" : { },
      "sv" : {
        "at0000.1" : {
          "@type" : "ARCHETYPE_TERM",
          "code" : "at0000.1",
          "text" : "Vårdenhet",
          "description" : "En enhet bestående av en eller flera personer och har ett särskilt syfte.\nI denna kontext är vårdenhet en organisatorisk enhet som tillhandahåller hälso- och sjukvård."
        },
        "at0003.1" : {
          "@type" : "ARCHETYPE_TERM",
          "code" : "at0003",
          "text" : "Identifierare",
          "description" : "Identifierare associerad med den identifierade organisationen.\nI denna kontext avses vårdenhetens identifierare.\n",
          "comment" : "Förekomster för detta dataelement är satt till 1..* för att tillåta att mer än en identifierare kan användas samtidigt. Observera att ID-datatypen innehåller flera underkomponenter för ID-värde, typ, utfärdare och tilldelare."
        },
        "at0004.1" : {
          "@type" : "ARCHETYPE_TERM",
          "code" : "at0004",
          "text" : "Roll",
          "description" : "Den roll eller kapacitet i vilken organisationen bidrar till vårdpersonens hälsa eller sociala vård.\nI denna kontext anger rollen att organisationen är av typ vårdenhet."
        },
        "at0001.1" : {
          "@type" : "ARCHETYPE_TERM",
          "code" : "at0001",
          "text" : "Namn",
          "description" : "Namnet som en organisation är känd för.\nI denna kontext avses vårdenhetens namn.",
          "comment" : "Exempelvis: 'Strömsbro hälsocentral', 'Vårdcentralen Blomman', 'Kirurgiska kliniken'."
        }
      }
    },
