  }, {
    "@type" : "TEMPLATE_OVERLAY",
    "uid" : "6b9832d3-3f5b-46ae-9d65-344a2be18e35",
    "description" : {
      "@type" : "RESOURCE_DESCRIPTION",
      "originalAuthor" : { },
