  }, {
    "@type" : "TEMPLATE_OVERLAY",
    "uid" : "7048783f-7d7f-4ac2-a022-e86bec10a095",
    "description" : {
      "@type" : "RESOURCE_DESCRIPTION",
      "originalAuthor" : { },
