      "details" : {
        "de" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "de"
          },
          "purpose" : "Zum Aufzeichnen zusammenfassender oder dauerhafter Informationen über Ereignisse in der Menstruationsgeschichte einer Person oder Menstruationsmuster im Laufe der Zeit.",
          "keywords" : [ "Menstruation, Menarche, Menopause, Wechseljahre, perimenopausal, postmenopausal" ],
          "use" : "Zur Aufzeichnung zusammenfassender oder dauerhafter Informationen über Menstruationsereignisse oder Menstruationsmuster einer Person im Laufe der Zeit.\r\n\r\nMehrere Instanzen des CLUSTERS \"Pro Episode\" ermöglichen die Zusammenfassung eines sich entwickelnden Verlaufs sowohl vergangener als auch gegenwärtiger Menstruationsepisoden oder -muster.\r\n\r\nDas Datenelement \"Letzte Aktualisierung\" erfasst das letzte Mal, dass die Menstruationszusammenfassung als Ganzes, einschließlich jeder Episode, aktualisiert wurde.\r\n\r\nVerwenden Sie das Datenelement \"Gesamtbeschreibung\", um die narrativen Beschreibungen der Menstruation oder der Menstruationsgeschichte in bestehenden oder älteren klinischen Systemen in ein archetypisches Format zu integrieren.",
          "misuse" : "Nicht für die Aufzeichnung von Informationen über einen bestimmten Menstruationszyklus zu verwenden. Verwenden Sie zu diesem Zweck OBSERVATION.menstruation.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "fi" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "fi"
          },
          "purpose" : "*To record an overview of the significant events related to menstrual cycle events.(en)",
          "keywords" : [ "*menstruation(en)", "*menstrual(en)", "*cycle(en)", "*period(en)", "*menarche(en)", "*menopause(en)", "*LNMP(en)" ],
          "use" : "*Use to record significant events related to the menstrual history.(en)",
          "misuse" : "*Not to be used to record information about a specific menstrual cycle. Use OBSERVATION.menstruation for this purpose. (en)",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "sv" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "sv"
          },
          "purpose" : "Att spela in sammanfattning eller ihållande information om en persons menstruationshistoriska händelser eller menstruationsmönster över tiden.",
          "keywords" : [ "menstruation", "mensdebut", "menopaus", "klimakteriet", "perimenopausal", "postmenopausal" ],
          "use" : "Används för att registrera sammanfattning eller ihållande information om en persons menstruationshistoriska händelser eller menstruationsmönster över tiden.\r\n\r\nFlera instanser av CLUSTER 'Per episod' tillåter sammanställning av en utvecklande historia av både tidigare och nuvarande episoder, eller mönster, av menstruation.\r\n\r\nDataelementet 'Senast uppdaterad' registrerar senaste gången som menstruationssammanfattningen som helhet, inklusive varje avsnitt, uppdaterades.\r\n\r\nAnvänds för att införliva de berättande beskrivningarna av menstruation eller menstruationshistoria i befintliga eller äldre kliniska system i ett arketypiskt format med hjälp av dataelementet \"Övergripande beskrivning\".",
          "misuse" : "Inte avsedd för att registrera information om en viss menstruationscykel. Använd OBSERVATION.menstruation för detta ändamål.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "nb" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "nb"
          },
          "purpose" : "For å registrere sammendrag og varig (persistent) informasjon om individets historikk knyttet til menstruasjon eller menstruasjonsmønstre over tid.",
          "keywords" : [ "menstruasjon", "menstruerende", "syklus", "menarke", "menopause", "overgangsalder", "mensen", "mens", "menarché", "blødningmønster" ],
          "use" : "Brukes for å registrere sammendrag eller varig (persistent) informasjon om et individs menstruasjonshistorikk eller menstruasjonsmønster over tid.\r\n\r\nFlere forekomster av det interne Clusteret 'Per episode' tillater sammenstilling av en utvikling av menstruasjonen i reproduktiv periode, for både tidligere og nåværende episoder.\r\n\r\nDataelementet \"Sist oppdatert\" vil bli brukt til å registrere siste gang menstruasjons-sammendraget som helhet ble oppdatert, inkludert hver episode.\r\n\r\nDataelementet \"Overordnet beskrivelse\" brukes til å overføre fritekstbeskrivelser av menstruasjon eller menstruasjonshistorikken fra eksisterende eller tidligere kliniske systemer til arketypeformat.",
          "misuse" : "Brukes ikke for å registrere detaljer om en spesifikk menstruasjonssyklus. Bruk arketypen \"Menstruasjon\" (OBSERVATION.menstruation) for dette formålet.\r\n",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "en" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "en"
          },
          "purpose" : "To record summary or persistent information about an individual's menstruation history events or patterns of menstruation over time.",
          "keywords" : [ "menstruation", "menarche", "menopause", "menopausal", "perimenopausal", "postmenopausal" ],
          "use" : "Use to record summary or persistent information about an individual's menstruation history events or patterns of menstruation over time.\r\n\r\nMultiple instances of the 'Per episode' CLUSTER will allow aggregation of an evolving history of both past and present episodes, or patterns, of menstruation.\r\n\r\nThe 'Last updated' data element will record the last time that the Menstruation summary as a whole, including each episode, was updated.\r\n\r\nUse to incorporate the narrative descriptions of Menstruation or menstrual history within existing or legacy clinical systems into an archetyped format, using the 'Overall description' data element.",
          "misuse" : "Not to be used to record information about a specific menstrual cycle. Use OBSERVATION.menstruation for this purpose.",
          "copyright" : "© openEHR Foundation",
          "originalResourceUri" : { },
          "otherDetails" : { }
        }
      }
