    "@type" : "TEMPLATE_OVERLAY",
    "uid" : "38783eca-4482-4ea5-ac07-ba1ca522706a",
    "description" : {
      "@type" : "RESOURCE_DESCRIPTION",
      "originalAuthor" : { },
      "otherContributors" : [ ],
      "ipAcknowledgements" : { },
      "references" : { },
      "conversionDetails" : { },
      "otherDetails" : {
        "PARENT:MD5-CAM-1.0.1" : "856c94ce6a084bbb4ff991d2698190c6"
      },
      "details" : {
        "de" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "de"
          },
          "purpose" : "Zur Darstellung der Umstände dahingehend, wie eine Person allein oder mit anderen zusammen lebt.",
          "keywords" : [ "allein", "solo", "Familie", "Freunde", "andere", "Haushalt" ],
          "use" : "Der Archetyp wird verwendet, um die Umstände darzustellen, wie eine Person alleine oder mit anderen lebt.\r\n\r\nDieses Archetyp wurde als einer von mehreren Archetypen entworfen, die die soziale Verbundenheit einer Person in ihrer häuslichen Umgebung beschreiben.\r\n\r\nIm Rahmen dieses Archetyps soll der Begriff \"Haushalt\" Informationen über eine oder mehrere Personen erfassen, die zusammen leben und Mahlzeiten, wirtschaftliche Ressourcen und/oder Wohnraum teilen. In diesem Kontext kann ein einzelner Haushalt verschiedene Formen annehmen, wie zum Beispiel Patchwork-Familien, eine Studenten-WG, eine Wohngruppe oder eine allein lebende Person. Eine einzelne Unterkunft kann als mehrere Haushalte betrachtet werden, wenn sie keine Mahlzeiten oder Ressourcen teilen oder getrennte Wohnräume haben.",
          "misuse" : "Nicht zur Darstellung allgemeiner Informationen über die aktuelle und vergangene Wohnsituation einer Person verwenden. Verwenden Sie dazu EVALUATION.housing_summary.\r\n\r\nDarf nicht verwendet werden, um Details der Wohnstätte, in der die Person wohnt, darzustellen – verwenden Sie CLUSTER.dwelling für diesen Zweck.\r\n\r\nNicht zur Beschreibung der sozialen Verbindungen der Person verwenden, einschließlich der Identifizierung von Haushaltsmitgliedern - verwenden Sie dafür EVALUATION.social_network.\r\n\r\nNicht zur Erfassung von Details zur Wohnsituation der Person oder des Wohnens für einen bestimmten Zeitraum verwenden. Verwenden Sie dafür CLUSTER.housing_record.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "nb" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "nb"
          },
          "purpose" : "For å registrere om et et individ bor alene eller sammen med andre.",
          "keywords" : [ "bor alene", "familie", "bokollektiv", "bofellesskap", "husholdning", "kollektiv", "hushold", "husstand" ],
          "use" : "For å registrere om et individ bor alene eller sammen med andre.\r\n\r\nDenne arketypen er en del av en arketypefamilie som beskriver den sosiale tilknytningen til et individs hjemmemiljø.\r\n\r\nI denne arketypen er intensjonen med begrepet 'boarrangement' å fange opp informasjon om en gruppe individer (en eller flere) som bor i samme bolig, inkludert å dele måltider, økonomiske ressurser og/eller boareal. En husholdning kan inkludere varianter av blandede familier, delt husholdning, bokollektiv, og et enkeltrom. Samtidig kan en enkelt bolig anses å inneholde flere husholdninger hvis de som bor der verken deler måltider eller økonomiske ressurser, eller har separat boareal.",
          "misuse" : "Skal ikke brukes til å registrere overordnet informasjon om et individs nåværende og tidligere bolig- eller bosituasjon. Bruk EVALUATION.housing_summary (Boligsammendrag) til dette formålet.\r\n\r\nSkal ikke brukes til å registrere detaljer om selve boligen der den enkelte bor - bruk CLUSTER.dwelling (Boligegenskaper) til dette formålet.\r\n\r\nSkal ikke brukes til å beskrive individets sosiale forbindelser, inkludert identifikasjon av husstandsmedlemmer - bruk EVALUATION.social_network (Sosialt nettverk) til dette formålet.\r\n\r\nSkal ikke brukes til å registrere detaljer om et individs bolig eller boform for en bestemt tidsperiode. Bruk CLUSTER.housing_record (Bolig) til dette formålet.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "en" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "en"
          },
          "purpose" : "To record the circumstances about how an individual lives alone or with others.",
          "keywords" : [ "alone", "solo", "family", "friends", "others", "household" ],
          "use" : "Use to record the circumstances about how an individual lives alone or with others. \r\n\r\nThis archetype has been designed as one of a family of archetypes that describe the social connectedness of an individual in their home environment.\r\n\r\nWithin this archetype, the intent of the concept of 'household' is to capture information about one or more people who reside together, including sharing meals, economic resources and/or living space. In this context, a single household might comprise varieties of blended families, a student share house, a group home, or a single person living alone. A single dwelling may be considered to contain multiple households if they don't share meals or resources, or have separate living spaces.",
          "misuse" : "Not to be used to record overall information about an individual's current and past housing or housing situation. Use EVALUATION.housing_summary for this purpose.\r\n\r\nNot to be used to record details of the dwelling where the individual resides - use CLUSTER.dwelling for this purpose.\r\n\r\nNot to be used to describe the social connections of the individual, including identification of household members - use EVALUATION.social_network for this purpose.\r\n\r\nNot to be used to record details of the individual's housing or housing for a specified period of time. Use CLUSTER.housing_record for this purpose.",
          "copyright" : "© openEHR Foundation",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "it" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "it"
          },
          "purpose" : "Registrare le circostanze di come un individuo vive da solo o con gli altri.",
          "keywords" : [ "da solo", "assolo", "famiglia", "amici", "altri", "famiglia" ],
          "use" : "*Use to record the circumstances about how an individual lives alone or with others. \r\n\r\nThis archetype has been designed as one of a family of archetypes that describe the social connectedness of an individual in their home environment.\r\n\r\nWithin this archetype, the intent of the concept of 'household' is to capture information about one or more people who reside together, including sharing meals, economic resources and/or living space. In this context, a single household might comprise varieties of blended families, a student share house, a group home, or a single person living alone. A single dwelling may be considered to contain multiple households if they don't share meals or resources, or have separate living spaces. (en)",
          "misuse" : "*Not to be used to record overall information about an individual's current and past housing or housing situation. Use EVALUATION.housing_summary for this purpose.\r\n\r\nNot to be used to record details of the dwelling where the individual resides - use CLUSTER.dwelling for this purpose.\r\n\r\nNot to be used to describe the social connections of the individual, including identification of household members - use EVALUATION.social_network for this purpose.\r\n\r\nNot to be used to record details of the individual's housing or housing for a specified period of time. Use CLUSTER.housing_record for this purpose. (en)",
          "originalResourceUri" : { },
