  }, {
    "@type" : "TEMPLATE_OVERLAY",
    "uid" : "65f749a8-6129-4461-a6e8-33907fbf858f",
    "description" : {
      "@type" : "RESOURCE_DESCRIPTION",
      "originalAuthor" : { },
      "otherContributors" : [ ],
      "ipAcknowledgements" : { },
      "references" : { },
      "conversionDetails" : { },
      "otherDetails" : {
        "PARENT:MD5-CAM-1.0.1" : "D2DAC3686CCA50254BAE94AAACD4BB96"
      },
      "details" : {
        "de" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "de"
          },
          "purpose" : "Zur Darstellung von klinischem Inhalt, der in bestehenden CLUSTER-Archetypen enthalten ist, als eigenständige Information in der Gesundheitsakte.",
          "keywords" : [ "generisch", "Container", "Slot" ],
          "use" : "Verwenden Sie diesen Archetyp, um den klinischen Inhalt, der in bestehenden CLUSTER-Archetypen enthalten ist und normalerweise im Kontext anderer Archetypen dargestellt wird, als eigenständige Daten in der Krankenakte darzustellen, wenn dies klinisch angemessen ist.\r\n\r\nDieser Archetyp soll nur als Container-Archetyp fungieren, der den flexiblen Ausdruck bestehender CLUSTER-Archetypen unterstützt. Es ist nicht beabsichtigt, andere Inhalte als den unbeschränkten SLOT zu enthalten.\r\n\r\nBeispielsweise wird der Archetyp openEHR-EHR-CLUSTER.tnm am häufigsten verwendet, um eine klinischen Klassifikation und Stadieneinteilung von Malignomen mit den Archetypen EVALUATION.problem_diagnosis bereitzustellen, aber durch Einfügen in diese OBSERVATION kann er die Information außerhalb des Kontexts einer Diagnose dargestellt werden, wenn dies klinisch angemessen ist . In ähnlicher Weise wird CLUSTER.tos normalerweise von HNO-Ärzten im Rahmen einer Untersuchung mit CLUSTER.exam_tympanic_membrane dargestellt, aber durch Einfügen in diesen Archetyp kann er außerhalb des Kontexts von Untersuchungsbefunden dargestellt werden, wenn dies klinisch angemessen ist.",
          "misuse" : "Darf nicht zur Darstellung spezifischer klinischer Inhalte verwendet werden, die in diesem Archetyp definiert sind.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "sv" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "sv"
          },
          "purpose" : "Gör det möjligt att representera det kliniska innehållet i CLUSTER-arketyper som fristående data i patientjournaler.",
          "keywords" : [ "allmän", "behållare" ],
          "use" : "Används i CLUSTER-arketyper för att göra det möjligt att när så är kliniskt lämpligt representera kliniskt innehåll som fristående data i patientjournaler. \r\n\r\nDenna arketyp är enbart tänkt att fungera som en behållare som stödjer flexibiliteten hos befintliga CLUSTER-arketyper. Arketypen är inte avsedd för annat innehåll än den ospärrade SLOT-arketypen.\r\n\r\nExempelvis används arketypen CLUSTER.nyha_heart_failure vanligtvis med arketypen EVALUATION.problem_diagnosis för att dokumentera en standardiserad bedömning av hjärtsvikt; om så är kliniskt lämpligt kan den i stället infogas i denna OBSERVATION-arketyp och därigenom användas i en annan kontext än EVALUATION. På liknande sätt dokumenteras CLUSTER.tos vanligtvis med CLUSTER.exam_tympanic_membrane av en ÖNH-specialist under en undersökning; om så är kliniskt lämpligt kan den i stället infogas i denna arketyp och därigenom användas i en annan kontext än som ett undersökningsresultat.",
          "misuse" : "Ska inte användas för att representera specifikt kliniskt innehåll definierat i denna arketyp.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "nb" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "nb"
          },
          "purpose" : "For å legge til rette for at klinisk innhold som finnes i et eksisterende CLUSTER skal kunne representeres som stand alone data i pasientjournalen.",
          "keywords" : [ "generisk", "container", "slot" ],
          "use" : "Brukes for å la det kliniske innholdet i eksisterende CLUSTER-arketyper, og vanligvis representert i sammenheng med andre arketyper, representeres som frittstående data i helsejournalen når det er klinisk hensiktsmessig.\r\n\r\nDenne arketypen er kun ment å fungere som en beholderarketype som støtter fleksibelt uttrykk for eksisterende CLUSTER-arketyper. Det er ikke ment å inneholde annet innhold enn den ubegrensede SLOT.\r\n\r\nFor eksempel er CLUSTER.nyha_heart_failure-arketypen mest brukt for å gi en standardisert vurdering av hjertesvikt med EVALUATION.problem_diagnosis-arketyper, men ved å sette den inn i denne OBSERVASJONEN kan den registreres som data utenfor konteksten av en diagnose, hvis det er klinisk hensiktsmessig. . Tilsvarende registreres CLUSTER.tos vanligvis av ØNH-spesialister i sammenheng med en undersøkelse ved bruk av CLUSTER.exam_tympanic_membrane, men ved å sette den inn i denne arketypen, gjør den at den kan registreres utenfor konteksten av undersøkelsesfunn, hvis det er klinisk hensiktsmessig.",
          "misuse" : "Not to be used to represent specific clinical content defined within this archetype.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "en" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "en"
          },
          "purpose" : "To enable the clinical content held within existing CLUSTER archetypes to be represented as standalone data in the health record.",
          "keywords" : [ "generic", "container", "slot" ],
          "use" : "Use to enable the clinical content held within existing CLUSTER archetypes, and usually represented within the context of other archetypes, to be represented as standalone data in the health record when clinically appropriate. \r\n\r\nThis archetype is intended only to act as a container archetype that supports flexible expression of existing CLUSTER archetypes. It is not intended to hold any content other than the unconstrained SLOT.\r\n\r\nFor example, the CLUSTER.nyha_heart_failure archetype is most commonly used to provide a standardised assessment of heart failure with EVALUATION.problem_diagnosis archetypes, but by inserting it within this OBSERVATION allows it to be recorded as data outside the context of a Diagnosis, if clinically appropriate. Similarly CLUSTER.tos is usually recorded by ENT specialists in the context of an examination using CLUSTER.exam_tympanic_membrane, but by inserting it into this archetype, it allows it to be recorded outside the context of examination findings, if clinically appropriate.",
          "misuse" : "Not to be used to represent specific clinical content defined within this archetype.",
          "copyright" : "© openEHR Foundation",
          "originalResourceUri" : { },
          "otherDetails" : { }
        }
      }
    },
