            "codeString" : "pt-br"
          },
          "purpose" : "Possibilita que o conteúdo clínico de um arquétipo CLUSTER existente seja representado como um dado independente em um registro de saúde.",
          "keywords" : [ "genérico", "conteiner", "slot" ],
          "use" : "Permite que o conteúdo de um arquétipo CLUSTER existente e geralmente representado dentro do contéudo de outros arquétipos seja representado como dado independente em um registro de saúde quando clinicamente apropriado.\r\n\r\nEste arquétipo deve ser utilizado apenas como um arquétipo container para flexibilizar o uso de um arquétipo CLUSTER existente. Ele não se destina a ser usado para representar qualquer conteúdo que não venha via seu SLOT irrestrito.\r\n\r\nPor exemplo, o arquétipo CLUSTER.nyha_heart_failure é geralmente usado para fornecer uma avaliação padronizada sobre insuficiência cardíaca com o arquétipo EVALUATION.problem_diagnosis, mas inserindo-o dentro de EVALUATION possiblita-se que ele seja registrado como dados fora do contexto de um Diagnóstico, se clinicamente apropriado. Da mesma forma, CLUSTER.tos é geralmente registrado por otorrinolaringologistas no contexto de um exame usando CLUSTER.exam_tympanic_membrane, mas inserindo-o neste arquétipo, possibilita-se que ele seja registrado fora do contexto dos achados clinicos, se clinicamente apropriado.",
          "misuse" : "Não deve ser usado para representar conteúdo clínico específico definido dentro deste arquétipo.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "en" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "en"
          },
          "purpose" : "To enable the clinical content held within existing CLUSTER archetypes to be represented as standalone data in the health record.",
          "keywords" : [ "generic", "container", "slot" ],
          "use" : "Use to enable the clinical content held within existing CLUSTER archetypes, and usually represented within the context of other archetypes, to be represented as standalone data in the health record when clinically appropriate. \r\n\r\nThis archetype is intended only to act as a container archetype that supports flexible expression of existing CLUSTER archetypes. It is not intended to hold any content other than the unconstrained SLOT.\r\n\r\nFor example, the CLUSTER.nyha_heart_failure archetype is most commonly used to provide a standardised assessment of heart failure with EVALUATION.problem_diagnosis archetypes, but by inserting it within this EVALUATION allows it to be recorded as data outside the context of a Diagnosis, if clinically appropriate. Similarly CLUSTER.tos is usually recorded by ENT specialists in the context of an examination using CLUSTER.exam_tympanic_membrane, but by inserting it into this archetype, it allows it to be recorded outside the context of examination findings, if clinically appropriate.",
          "misuse" : "Not to be used to represent specific clinical content defined within this archetype.",
          "copyright" : "© openEHR Foundation",
          "originalResourceUri" : { },
          "otherDetails" : { }
        }
      }
