              "value" : "ISO_639-1"
            },
            "codeString" : "en"
          },
          "purpose" : "To record a subset of persistent or summary information about the pregnancy and birth of an infant, that may be used within both the mother's and infant's health record.",
          "keywords" : [ "birth", "pregnancy", "infant", "newborn" ],
          "use" : "Use to record a subset of persistent or summary information about the pregnancy and birth of an infant, usually recorded as part of a maternal health record or birth report, but also able to be shared and reused to provide context about the pregnancy and birth within the newborn's health record.\r\n\r\nThis archetype has been designed to be nested:\r\n- in the 'Birth detail' SLOT within the EVALUATION.pregnancy_summary archetype, to capture details about an infant born to the mother; and\r\n- in the 'Birth detail' SLOT within the EVALUATION.birth_summary archetype, to capture or reuse details about the birth of the individual.",
          "copyright" : "© openEHR Foundation",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "es" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "es"
          },
          "purpose" : "Registrar un subconjunto de información persistente o resumida sobre el embarazo y el nacimiento de un bebé, que puede usarse tanto en el registro de salud de la madre como del bebé.",
          "keywords" : [ "nacimiento", "embarazo", "niño", "bebé", "infante", "recién nacido" ],
          "use" : "Se utiliza para registrar un subconjunto de información persistente o resumida sobre el embarazo y el nacimiento de un bebé, generalmente registrada como parte de un registro de salud materna o un informe de nacimiento, pero que también se puede compartir y reutilizar para proporcionar un contexto sobre el embarazo y el nacimiento dentro del contexto. Historial de salud del recién nacido.\r\n\r\nEste arquetipo ha sido diseñado para ser anidado:\r\n- en el nodo 'Detalle del nacimiento' dentro del arquetipo EVALUATION.pregnancy_summary, para capturar detalles sobre un bebé nacido de la madre; y\r\n- en el nodo 'Detalle de nacimiento' dentro del arquetipo EVALUATION.birth_summary, para capturar o reutilizar detalles sobre el nacimiento del individuo.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "ca" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "ca"
          },
          "purpose" : "Per registrar un subconjunt d'informació persistent o resumida sobre l'embaràs i el naixement d'un nadó, que es pot utilitzar tant al registre de salut de la mare com del nadó.",
          "keywords" : [ "naixement", "embaràs", "infant", "nounat" ],
          "use" : "S'utilitza per registrar un subconjunt d'informació persistent o resumida sobre l'embaràs i el naixement d'un nadó, normalment registrada com a part d'un registre de salut materna o d'un informe de naixement, però que també es pot compartir i reutilitzar per proporcionar context sobre l'embaràs i el part dins de l'historial de salut del nounat.\r\n\r\nAquest arquetip ha estat dissenyat per anidar:\r\n- al node (SLOT) 'Detall de naixement' dins de l'arquetip EVALUATION.pregnancy_summary, per captar detalls sobre un nadó nascut de la mare; i\r\n- al node (SLOT) \"Detall de naixement\" dins de l'arquetip EVALUATION.birth_summary, per capturar o reutilitzar detalls sobre el naixement de l'individu.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        }
      }
    },
